function parseNullableCoordinate(value: string) {
  return value ? Number(value) : null;
}

export const japanCityRecords: JapanCityRecord[] = rawJapanCityRecords
  .split("\n")
  .slice(1)
  .map((line) => {
    const [
      id,
      code,
      jisCode,
      prefecture,
      name,
      displayName,
      kana,
      level,
      type,
      parentId,
      latitude,
      longitude,
      building,
      address,
      coordinateSource,
      note,
      updatedAt
    ] = line.split("\t");

    return {
      id,
      code,
      jisCode,
      prefecture,
      name,
      displayName,
      kana,
      level: level as JapanCityLevel,
      type,
      parentId: parentId || null,
      latitude: parseNullableCoordinate(latitude),
      longitude: parseNullableCoordinate(longitude),
      building,
      address,
      coordinateSource,
      note,
      updatedAt
    };
  });
